tasks.solution:
from itertools import combinations

cols = ['student', 'course', 'room']
rows = [('kim', 'db', 'R1'), ('kim', 'os', 'R2'), ('lee', 'db', 'R1'), ('lee', 'os', 'R3')]


def unique(idx):
    # 고른 열의 값 묶음이 행마다 모두 다른지 봐요.
    seen = {tuple(row[i] for i in idx) for row in rows}
    return len(seen) == len(rows)


def candidate(idx):
    if not unique(idx):
        return False
    # 이 주석 아래에 최소성 검사를 쓰세요.
    if any(unique(tuple(j for j in idx if j != i)) for i in idx):
        return False
    return True


# 열 1개짜리 묶음부터 차례로 검사해 출력해요.
for k in range(1, len(cols) + 1):
    for idx in combinations(range(len(cols)), k):
        if candidate(idx):
            print('+'.join(cols[i] for i in idx))

